<script module>let pending=null</script>
<script>
  import { onMount, onDestroy, tick } from 'svelte'
  import { Plus, ChevronDown } from 'lucide-svelte'
  import { getWorkflowLibrary, getWorkflowEditor, getPreparedTasks, createPreparedTask } from './api.js'
  import './configuration-controls.css'
  let tasks=$state([]),presets=$state([]),checkout=$state(''),writable=$state(false),open=$state(false),loading=$state(true),busy=$state(false),error=$state(''),notice=$state(''),status=$state(),titleInput=$state(),discard=$state(false)
  let id=$state(''),title=$state(''),brief=$state(''),workflow=$state(''),assurance=$state('standard'),validation=$state(''),base=$state(''),head=$state(''),view=$state(null),reading=$state(false),generation=0
  let selected=$derived(presets.find(item=>item.name===workflow)),dirty=$derived(open && !!(title || brief))
  async function refresh(){loading=true;error='';try{const [library,local]=await Promise.all([getWorkflowLibrary(),getPreparedTasks()]);presets=library.presets;tasks=local.tasks;checkout=local.checkout;writable=local.writable}catch(cause){error=cause.message}finally{loading=false}}
  async function readSelection(){const token=++generation;view=null;reading=false;if(!selected)return;reading=true;try{const result=await getWorkflowEditor(selected.shape,assurance,workflow);if(token===generation)view=result}catch(cause){if(token===generation)error=cause.message}finally{if(token===generation)reading=false}}
  async function choose(value){workflow=value;assurance=presets.find(item=>item.name===value)?.suggested_assurance || 'standard';await readSelection()}
  onMount(async()=>{await refresh();if(pending){({id,title,brief,workflow,assurance,validation,base,head}=pending);open=true;pending=null;await readSelection()}})
  onDestroy(()=>{generation++;if(dirty)pending={id,title,brief,workflow,assurance,validation,base,head}})
  async function newTask(){id=crypto.randomUUID();title='';brief='';workflow='';view=null;validation='';base='';head='';open=true;discard=false;notice='';error='';await tick();titleInput?.focus()}
  async function submit(){busy=true;error='';try{const result=await createPreparedTask({id,title,brief,workflow,assurance,revision:view.revision,policy_revision:view.policy_revision,validation_command:validation,review_base:base,review_head:head});tasks=[result.task,...tasks.filter(task=>task.id!==result.task.id)];open=false;pending=null;notice='Task saved locally. No agents were started. Open its launch details when you are ready.';await tick();status?.focus()}catch(cause){error=cause.message}finally{busy=false}}
  function beforeUnload(event){if(dirty){event.preventDefault();event.returnValue=''}}
  async function copy(text){try{await navigator.clipboard.writeText(text);notice='Command copied.'}catch{notice='Could not copy automatically. Select the command text below to copy it.'}}
</script>
<svelte:window onbeforeunload={beforeUnload} />
<section class="local-tasks" aria-label="Local task preparation">
  <header><div><h2>Local tasks</h2><p>Prepare a brief with a saved workflow, then launch through Crew when ready.</p></div><button class="primary" disabled={loading || !writable || open} onclick={newTask}><Plus size={16} aria-hidden="true" />New task</button></header>
  {#if notice}<p class="notice" role="status" tabindex="-1" bind:this={status}>{notice}</p>{/if}
  {#if error}<div class="error" role="alert">{error}<button disabled={busy} onclick={async()=>{await refresh();await readSelection()}}>Reload configuration</button></div>{/if}
  {#if loading}<p role="status">Reading local tasks…</p>{:else if !writable}<p>This installation is read-only. Open its source checkout to create a task.</p>{/if}
  {#if open}<form onsubmit={event=>{event.preventDefault();submit()}}><fieldset disabled={busy}>
    <label>Task title<input bind:this={titleInput} bind:value={title} required maxlength="160" placeholder="What should this task accomplish?" /></label>
    <label>Brief<textarea bind:value={brief} required maxlength="64000" rows="5" placeholder="Describe the result, relevant context and how to verify success."></textarea></label>
    <p class="project"><strong>Project</strong><span>{checkout}</span></p>
    <div class="fields"><label>Saved workflow<div class="select-shell"><select value={workflow} required onchange={event=>choose(event.currentTarget.value)}><option value="" disabled>Choose a saved preset</option>{#each presets as preset}<option value={preset.name} disabled={!preset.compatible_assurances.length}>{preset.name}{preset.error?' · needs attention':''}</option>{/each}</select><ChevronDown size={16} aria-hidden="true" /></div></label><label>Assurance<div class="select-shell"><select bind:value={assurance} disabled={!selected} onchange={readSelection}>{#each selected?.compatible_assurances || ['standard'] as name}<option value={name}>{name[0].toUpperCase()+name.slice(1)}</option>{/each}</select><ChevronDown size={16} aria-hidden="true" /></div></label></div>
    {#if !presets.some(item=>item.compatible_assurances.length)}<p>No usable saved presets yet. <a href="#/workflows">Save a workflow first</a>.</p>{/if}
    {#if reading}<p role="status">Reading assignments…</p>{:else if view}<div class="assignment-summary"><strong>Assignments for {workflow}</strong><ul>{#each Object.entries(view.map.seats) as [stage,cells]}{#each Array.isArray(cells)?cells:[cells] as cell}<li><span>{stage} · {cell.role}</span><b>{cell.id}</b><small>{cell.agent} · {cell.effort} effort</small></li>{/each}{/each}</ul><p>The saved revision is pinned. If the preset changes, boot will ask you to prepare the task again.</p></div>{/if}
    {#if ['repair','directed','finish'].includes(selected?.shape)}<label>Validation command<input bind:value={validation} placeholder="e.g. npm test" /></label>{/if}
    {#if ['review_only','review_panel','verify_only'].includes(selected?.shape)}<div class="fields"><label>Review base commit<input bind:value={base} placeholder="Full Git commit ID" /></label><label>Review head commit<input bind:value={head} placeholder="Full Git commit ID" /></label></div><p>Missing commit IDs can be kept in a prepared task, but launch commands need both.</p>{/if}
    {#if ['repair','finish'].includes(selected?.shape)}<p class="notice">This workflow needs prior task context. You can save the brief here; launch it from the existing task through the Crew CLI.</p>{/if}
    </fieldset><div class="actions"><button class="primary" type="submit" disabled={busy || reading || !view?.revision || !!view?.validation}>{busy?'Saving…':'Create local task'}</button><button type="button" disabled={busy} onclick={()=>{if(dirty)discard=true;else open=false}}>Cancel</button></div>
    {#if discard}<div class="notice" role="alert"><p>Discard this unsaved task?</p><div class="actions"><button type="button" onclick={()=>discard=false}>Keep editing</button><button type="button" onclick={()=>{open=false;discard=false;pending=null}}>Discard draft</button></div></div>{/if}
  </form>{/if}
  {#if tasks.length}<ul class="task-drafts">{#each tasks as task}<li><details><summary><strong>{task.title}</strong><span>{task.workflow} · {task.assurance} · prepared locally</span></summary><p>{task.brief}</p>{#if task.requirements.length}<ul>{#each task.requirements as requirement}<li>{requirement}</li>{/each}</ul>{:else}<p>Run these commands in order. Boot configures the task; run starts its workflow. Current runtime checks still apply.</p>{#each task.commands as command}<div class="command"><div><strong>{command.label}</strong><button onclick={()=>copy(command.text)}>Copy</button></div><pre>{command.text}</pre></div>{/each}{/if}<p class="hint">Brief saved at {task.brief_path}. This preparation record does not track execution status; running tasks appear in history below.</p></details></li>{/each}</ul>{/if}
</section>
<style>
.local-tasks{display:grid;gap:1rem;margin:1.5rem 0 2rem;padding:1.25rem;border:1px solid var(--line);border-radius:.75rem;background:var(--panel);min-width:0}header{display:flex;justify-content:space-between;align-items:start;gap:1rem}h2,p{margin:0}h2{font-size:1.15rem}p{color:var(--muted);line-height:1.5;font-size:.9rem;margin-top:.4rem}button,input,select,textarea{font:inherit}button{display:inline-flex;align-items:center;justify-content:center;gap:.4rem;min-height:2.65rem;padding:.6rem .85rem;border:1px solid var(--line);border-radius:.5rem;color:var(--text);background:var(--panel);cursor:pointer}button:disabled{opacity:.55;cursor:default}.primary{color:var(--on-accent);background:var(--accent-solid);border-color:var(--accent-solid)}form,fieldset{display:grid;gap:1.1rem;min-width:0}fieldset{border:0;margin:0;padding:0}label{display:grid;gap:.45rem;font-size:.9rem;font-weight:600;min-width:0}input,select,textarea{width:100%;box-sizing:border-box;min-width:0;padding:.7rem;border:1px solid var(--muted);border-radius:.45rem;color:var(--text);background:var(--panel)}select{padding-inline-end:2.8rem}textarea{resize:vertical;line-height:1.5}.fields{display:grid;align-items:start;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:1.25rem}.project{display:grid;gap:.25rem;overflow-wrap:anywhere}.project strong{color:var(--text)}.actions{display:flex;flex-wrap:wrap;gap:.75rem}.notice,.error{padding:.85rem;border:1px solid var(--line);border-radius:.5rem;overflow-wrap:anywhere}.notice{border-inline-start:3px solid var(--accent)}.error{color:var(--status-fail)}.error button{margin-inline-start:.75rem}a{color:var(--accent)}.assignment-summary{padding:1rem;background:var(--panel-raised);border-radius:.5rem}.assignment-summary ul,.task-drafts{list-style:none;margin:0;padding:0}.assignment-summary li{display:grid;grid-template-columns:1fr 1fr;gap:.3rem .75rem;padding:.6rem 0;font-size:.85rem;overflow-wrap:anywhere}.assignment-summary small{color:var(--muted)}.task-drafts>li{border-top:1px solid var(--line);padding-top:.75rem;margin-top:.75rem}summary{cursor:pointer;display:list-item}summary strong,summary span{display:block;font-size:.9rem}summary span,.hint{color:var(--muted);font-size:.8rem;overflow-wrap:anywhere}details>p{white-space:pre-wrap}.command{margin-top:1rem}.command>div{display:flex;justify-content:space-between;align-items:center;gap:1rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--panel-raised);padding:1rem;border-radius:.5rem;font-size:.8rem}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:600px){.fields,.assignment-summary li{grid-template-columns:1fr}.local-tasks{padding:1rem}header{flex-wrap:wrap}}
</style>
